"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";
import styles from "../styles/draw-border-card.module.css";

export interface DrawBorderCardProps {
  /** Card heading (ignored when children are provided) */
  title?: string;
  /** Card body copy (ignored when children are provided) */
  body?: string;
  /** Custom card content */
  children?: React.ReactNode;
  /** Stroke draw duration in seconds */
  duration?: number;
  /** Stroke color */
  strokeColor?: string;
  /** Stroke width in pixels */
  strokeWidth?: number;
  /** Card corner radius in pixels (shared by the card and the stroke) */
  radius?: number;
  /** Optional className */
  className?: string;
}

export function DrawBorderCard({
  title = "Draw Border Card",
  body = "Hover or focus the card and a single stroke traces its outline, matched exactly to the corner radius.",
  children,
  duration = 0.8,
  strokeColor = "#38bdf8",
  strokeWidth = 2,
  radius = 16,
  className = "",
}: DrawBorderCardProps) {
  const prefersReducedMotion = useReducedMotion();
  const [hovered, setHovered] = React.useState(false);
  const [focused, setFocused] = React.useState(false);
  const active = hovered || focused;

  return (
    <article
      tabIndex={0}
      onPointerEnter={() => setHovered(true)}
      onPointerLeave={() => setHovered(false)}
      onFocus={() => setFocused(true)}
      onBlur={(e) => {
        if (!e.currentTarget.contains(e.relatedTarget as Node | null)) setFocused(false);
      }}
      data-active={active || undefined}
      style={{ "--mf-db-radius": `${radius}px` } as React.CSSProperties}
      className={`${styles.root} ${className}`.trim()}
    >
      <svg className={styles.outline} aria-hidden="true">
        <motion.rect
          x="0"
          y="0"
          width="100%"
          height="100%"
          rx={radius}
          ry={radius}
          fill="none"
          stroke={strokeColor}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          initial={false}
          animate={
            prefersReducedMotion
              ? { pathLength: 1, opacity: active ? 1 : 0 }
              : { pathLength: active ? 1 : 0, opacity: active ? 1 : 0 }
          }
          transition={
            prefersReducedMotion
              ? { duration: 0.15 }
              : {
                  pathLength: { duration, ease: [0.65, 0, 0.35, 1] },
                  opacity: { duration: 0.12, delay: active ? 0 : duration * 0.6 },
                }
          }
        />
      </svg>
      <div className={styles.content}>
        {children ?? (
          <>
            <h3 className={styles.title}>{title}</h3>
            <p className={styles.body}>{body}</p>
          </>
        )}
      </div>
    </article>
  );
}

.root {
  position: relative;
  display: block;
  width: 18rem;
  max-width: 100%;
  padding: 1.5rem;
  box-sizing: border-box;
  border-radius: var(--mf-db-radius, 16px);
  border: 1px solid var(--mf-border, #2e2e38);
  background: radial-gradient(120% 90% at 50% 0%, var(--mf-surface-raised, #1b1b22) 0%, var(--mf-surface, #121218) 75%);
  color: var(--mf-fg, #f4f4f6);
}

.root:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: 3px;
}

/* Covers the border box so the stroke sits exactly on the rounded edge. */
.outline {
  position: absolute;
  inset: -1px;
  width: calc(100% + 2px);
  height: calc(100% + 2px);
  overflow: visible;
  pointer-events: none;
}

.content {
  position: relative;
}

.title {
  margin: 0 0 0.5rem;
  font-size: 1.15rem;
  font-weight: 650;
  letter-spacing: -0.02em;
}

.body {
  margin: 0;
  font-size: 0.875rem;
  line-height: 1.55;
  color: var(--mf-muted, #a1a1aa);
}

@media (prefers-reduced-motion: reduce) {
  .outline rect {
    transition: none;
  }
}

