"use client";

import { motion } from "motion/react";

export function DrawBorderCardTailwind({ title = "Draw Border Card", body = "A single stroke traces the outline on hover or focus." }) {
  return (
    <motion.article
      tabIndex={0}
      initial="rest"
      animate="rest"
      whileHover="active"
      whileFocus="active"
      className="relative w-72 rounded-2xl border border-zinc-800 bg-zinc-900 p-6 text-zinc-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-[3px] focus-visible:outline-zinc-200"
    >
      <svg aria-hidden className="pointer-events-none absolute -inset-px h-[calc(100%+2px)] w-[calc(100%+2px)] overflow-visible">
        <motion.rect
          width="100%"
          height="100%"
          rx="16"
          fill="none"
          stroke="#38bdf8"
          strokeWidth="2"
          variants={{ rest: { pathLength: 0, opacity: 0 }, active: { pathLength: 1, opacity: 1 } }}
          transition={{ duration: 0.8, ease: "easeInOut" }}
        />
      </svg>
      <h3 className="mb-2 text-lg font-semibold">{title}</h3>
      <p className="text-sm text-zinc-400">{body}</p>
    </motion.article>
  );
}
